91	/**
92	 * Escapes a key for use in a JSON path expression.
93	 * Handles backslashes and double quotes which have special meaning in JSON paths.
94	 */
95	export function escapeJsonPathKey(key: string): string {
96	  return key.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
97	}
